import{_ as e,o as a,c as o,a2 as i}from"./chunks/framework.CNDaxUod.js";const l="/docs/assets/i1.zlxjrWsa.png",s="/docs/assets/i2.CHUR5yQy.png",n="/docs/assets/i3.oW0g3FHN.png",r="/docs/assets/i4.9w7Goy63.png",c="/docs/assets/i5.Bi-C-F_B.png",w=JSON.parse('{"title":"How to install the SCTP mod?","description":"","frontmatter":{},"headers":[],"relativePath":"installation.md","filePath":"installation.md"}'),d={name:"installation.md"};function h(p,t,u,m,f,g){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="how-to-install-the-sctp-mod" tabindex="-1">How to install the SCTP mod? <a class="header-anchor" href="#how-to-install-the-sctp-mod" aria-label="Permalink to &quot;How to install the SCTP mod?&quot;">​</a></h1><details class="details custom-block"><summary>Table of Contents/Overview</summary><nav class="table-of-contents"><ul><li><a href="#installing-fabric">Installing Fabric</a><ul><li><a href="#downloading-running-the-installer">Downloading &amp; running the installer</a></li><li><a href="#launching-minecraft">Launching Minecraft</a></li></ul></li><li><a href="#downloading-the-fabric-api">Downloading the Fabric API</a></li><li><a href="#downloading-the-sctp-mod">Downloading the SCTP mod</a></li><li><a href="#installing-the-mod-files">Installing the mod files</a></li><li><a href="#done">Done</a></li></ul></nav></details><div class="warning custom-block"><p class="custom-block-title">Forge support</p><p>Forge is currently not supported. I am working on it, though!</p></div><div class="danger custom-block"><p class="custom-block-title">1.21.11 &amp; 26.1 EOL</p><p>Minecraft version 1.21.11 and 26.1 will no longer be supported after mod version 1.5.2, as Snailcraft has updated to 26.2 - please update!</p></div><h2 id="installing-fabric" tabindex="-1">Installing Fabric <a class="header-anchor" href="#installing-fabric" aria-label="Permalink to &quot;Installing Fabric&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Important:</p><p>This tutorial assumes you are using the default MC launcher. If you use Modrinth, Prism, Lunar, Feather, or a similar modded launcher, a different method may apply. I recommend you to use Google if that is the case.</p></div><h3 id="downloading-running-the-installer" tabindex="-1">Downloading &amp; running the installer <a class="header-anchor" href="#downloading-running-the-installer" aria-label="Permalink to &quot;Downloading &amp; running the installer&quot;">​</a></h3><p>Start by downloading and running the <a href="https://fabricmc.net/use/installer/" target="_blank" rel="noreferrer">official Fabric installer</a>. You will see a screen like this: <img src="'+l+'" alt="1"></p><div class="tip custom-block"><p class="custom-block-title">I: Please select the Minecraft version. For the SCTP mod, select 26.2.</p></div><div class="tip custom-block"><p class="custom-block-title">II: Please select the most recent loader version available, usually selected by default.</p></div><div class="tip custom-block"><p class="custom-block-title">III: Please make sure the Launcher Location is correct. Usually, the default will be correct.</p></div><div class="tip custom-block"><p class="custom-block-title">IV: Make sure &#39;Create profile&#39; is checked, and press &#39;Install&#39;.</p></div><h3 id="launching-minecraft" tabindex="-1">Launching Minecraft <a class="header-anchor" href="#launching-minecraft" aria-label="Permalink to &quot;Launching Minecraft&quot;">​</a></h3><p>Run the new profile created by the launcher first, so it can make the mods folder. Make sure the correct profile is selected (fabric-loader-XXX) and press play. <img src="'+s+'" alt="2"></p><h2 id="downloading-the-fabric-api" tabindex="-1">Downloading the Fabric API <a class="header-anchor" href="#downloading-the-fabric-api" aria-label="Permalink to &quot;Downloading the Fabric API&quot;">​</a></h2><p>Next up, we will download the Fabric API - it&#39;s a mod that is required for the SCTP mod to function. Start by going to the page on <a href="https://www.curseforge.com/minecraft/mc-mods/fabric-api" target="_blank" rel="noreferrer">curseforge</a>. <img src="'+n+'" alt="alt text"></p><div class="tip custom-block"><p class="custom-block-title">I: Select the same game version you picked during the installation process, in this case 26.2.</p></div><div class="tip custom-block"><p class="custom-block-title">II: Press download, and put the file in a place you will remember for later.</p></div><h2 id="downloading-the-sctp-mod" tabindex="-1">Downloading the SCTP mod <a class="header-anchor" href="#downloading-the-sctp-mod" aria-label="Permalink to &quot;Downloading the SCTP mod&quot;">​</a></h2><p>Next, we will download the SCTP mod, called shoplogger. You can download it by going to the <a href="https://sctp.nl/" target="_blank" rel="noreferrer">sctp homepage</a> and pressing the Download button.</p><div class="tip custom-block"><p class="custom-block-title">I: Select the correct game version (26.2) and put it in a place to remember for later.</p></div><p><img src="'+r+'" alt="alt text"></p><div class="info custom-block"><p class="custom-block-title">Safety</p><p>If you want to confirm the source code yourself before downloading, you can check out the <a href="https://github.com/maxolotled/sctp" target="_blank" rel="noreferrer">github repository</a>.</p></div><h2 id="installing-the-mod-files" tabindex="-1">Installing the mod files <a class="header-anchor" href="#installing-the-mod-files" aria-label="Permalink to &quot;Installing the mod files&quot;">​</a></h2><p>For the last step, we need to put the mod files into the directory of the Fabric installation we made. Start by navigating to where you put the two downloaded mod files. <img src="'+c+'" alt="alt text"></p><div class="tip custom-block"><p class="custom-block-title">I: Copy the mod files: one for fabric API and one for SCTP.</p></div><div class="tip custom-block"><p class="custom-block-title">II: Navigate to the mod directory by pasting <code>%appdata%\\.minecraft\\mods</code> in your navigator bar (marked with the arrow), or open the folder via your launcher</p></div><div class="tip custom-block"><p class="custom-block-title">III: Paste the files into this mods folder.</p></div><h2 id="done" tabindex="-1">Done <a class="header-anchor" href="#done" aria-label="Permalink to &quot;Done&quot;">​</a></h2><p>Congratulations, you have successfully installed the SCTP mod into your Minecraft, and can now start using it! Thank you for helping maintain the website. Check out the <a href="./features">features</a> now!</p>',30)])])}const k=e(d,[["render",h]]);export{w as __pageData,k as default};
